<script>
    BX.ready(function () {


        function scrollToJakor() {

            document.querySelectorAll('.smooth2').forEach(anchor => {
                anchor.addEventListener('click', function (e) {
                    e.preventDefault(); // Отменяем стандартный переход
                    alert('ok');
                    const targetId = this.getAttribute('href'); // Получаем ID из href
                    const targetElement = document.querySelector(targetId);

                    if (targetElement) {
                        targetElement.scrollIntoView({
                            behavior: 'smooth',
                            block: 'start', // Выравнивание по верху
                            inline: 'nearest'
                        });
                    }
                });
            });
        }

    )}
</script>
